"use strict";(()=>{const e=Array.from(document.querySelectorAll(".reveal"));if("IntersectionObserver"in window){const t=new IntersectionObserver((e,t)=>{e.forEach(e=>{if(e.isIntersecting){const s=e.target,r=Number(s.getAttribute("data-delay")||0);window.setTimeout(()=>s.classList.add("is-visible"),1e3*r+80),t.unobserve(s)}})},{threshold:.15});e.forEach(e=>t.observe(e))}else e.forEach((e,t)=>{const s=Number(e.getAttribute("data-delay")||0);window.setTimeout(()=>e.classList.add("is-visible"),1e3*s+40*t+80)})})();